async function seedDemoData() {
  if (process.env.SEED_DEMO_BRAND === "0") {
    logger2.info("SEED_DEMO_BRAND=0 \u2014 skipping demo brand seed (white-label install)");
    return;
  }
  try {
    for (const brand of DEMO_BRANDS) {
      const existing = await db.select().from(brandsTable).where(eq(brandsTable.name, brand.name)).limit(1);
      if (existing.length === 0) {
        await db.insert(brandsTable).values(brand);
        logger2.info(`Seeded brand: ${brand.name}`);
      }
    }
  } catch (err) {
    logger2.error({ err }, "Failed to seed demo data");
  }
}

